+import { minorUnitFactor } from './money';
+
+export interface ExportInvoice {
+  invoiceNumber: string;
+  company: { name: string };
+  currencyCode: string;
+  issueDate: Date | string;
+  dueDate: Date | string | null;
+  totalMinor: number;
+  paidMinor: number;
+  status: string;
+}
+
+export function balanceDue(invoice: Pick<ExportInvoice, 'status' | 'totalMinor' | 'paidMinor'>): number {
+  return ['SENT', 'PARTIAL', 'OVERDUE'].includes(invoice.status)
+    ? Math.max(0, invoice.totalMinor - invoice.paidMinor) : 0;
+}
+
+export function exportAmount(value: number, currency: string): string {
+  const amount = BigInt(Math.round(value));
+  const negative = amount < 0n;
+  const absolute = negative ? -amount : amount;
+  const factor = BigInt(minorUnitFactor(currency));
+  return `${negative ? '-' : ''}${absolute / factor}${factor === 1n ? '' : '.' + String(absolute % factor).padStart(2, '0')}`;
+}
+
+const date = (value: Date | string | null) => value ? new Date(value).toISOString().slice(0, 10) : '';
+const quote = (value: string) => /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
+
+export function invoiceCsv(invoices: readonly ExportInvoice[]): string {
+  const rows = [['invoice_number','company','currency','issue_date','due_date','total','paid','balance_due','status'],
+    ...invoices.map(i => [i.invoiceNumber,i.company.name,i.currencyCode.toUpperCase(),date(i.issueDate),date(i.dueDate),
+      exportAmount(i.totalMinor,i.currencyCode),exportAmount(i.paidMinor,i.currencyCode),exportAmount(balanceDue(i),i.currencyCode),i.status])];
+  return '\uFEFF' + rows.map(row => row.map(quote).join(',')).join('\r\n') + '\r\n';
+}
