+import { balanceDue } from './invoice-export';
+
+export const AGING_BUCKETS = ['current', '1-30', '31-60', '61-90', '90+'] as const;
+export type AgingBucket = (typeof AGING_BUCKETS)[number];
+export interface AgingInvoice {
+  status: string;
+  currencyCode: string;
+  totalMinor: number;
+  paidMinor: number;
+  dueDate: string | null;
+}
+export interface AgingRow {
+  currency: string;
+  buckets: Record<AgingBucket, number>;
+  totalMinor: number;
+}
+export function agingReport(invoices: readonly AgingInvoice[], asOf: string): AgingRow[] {
+  const today = Date.parse(asOf + 'T00:00:00.000Z');
+  const rows = new Map<string, AgingRow>();
+  for (const invoice of invoices) {
+    const balance = balanceDue(invoice);
+    if (balance <= 0) continue;
+    const days = invoice.dueDate ? Math.floor((today - Date.parse(invoice.dueDate + 'T00:00:00.000Z')) / 86400000) : 0;
+    const bucket: AgingBucket = days <= 0 ? 'current' : days <= 30 ? '1-30' : days <= 60 ? '31-60' : days <= 90 ? '61-90' : '90+';
+    const currency = invoice.currencyCode.toUpperCase();
+    const row = rows.get(currency) ?? {currency, buckets: {current:0,'1-30':0,'31-60':0,'61-90':0,'90+':0},totalMinor:0};
+    row.buckets[bucket] += balance;
+    row.totalMinor += balance;
+    rows.set(currency, row);
+  }
+  return [...rows.values()].sort((a,b)=>a.currency.localeCompare(b.currency));
+}
