+function internationalNumber(value: string | null | undefined): string | null {
+  if (!value) return null;
+  let number = value.replace(/[\s.()\-]/g, '');
+  if (!/^\+?\d+$/.test(number)) return null;
+  if (number.startsWith('+')) number = number.slice(1);
+  else if (number.startsWith('00')) number = number.slice(2);
+  else if (number.startsWith('0')) number = '84' + number.slice(1);
+  return /^[1-9]\d{7,14}$/.test(number) ? number : null;
+}
+export function phoneUrl(value: string | null | undefined): string | null {
+  const number = internationalNumber(value);
+  return number ? 'tel:+' + number : null;
+}
+export function whatsappUrl(value: string | null | undefined): string | null {
+  const number = internationalNumber(value);
+  return number ? 'https://wa.me/' + number : null;
+}
+export function telegramUrl(value: string | null | undefined): string | null {
+  if (!value) return null;
+  const match = value.trim().match(/^(?:(?:https?:\/\/)?t\.me\/([A-Za-z][A-Za-z0-9_]{4,31})\/?|@?([A-Za-z][A-Za-z0-9_]{4,31}))$/);
+  return match ? 'https://t.me/' + (match[1] ?? match[2]) : null;
+}
